import SwiftUI

/// The v3 palette (docs/advice/fable-v3-web-2026-10-26.md 2.2) as named colours of
/// `Colors.xcassets`, each with light, dark and increased-contrast variants. Generated by
/// `Scripts/make_colours.py`.
extension Color {
    /// Behind everything.
    static let board = Color("Board")
    /// Grouped content, sheets, inputs.
    static let surface = Color("Surface")
    /// Controls at rest, empty tips.
    static let fill = Color("Fill")
    /// Pressed and selected.
    static let fill2 = Color("Fill2")
    static let line = Color("Line")
    static let line2 = Color("Line2")
    static let ink = Color("Ink")
    static let ink2 = Color("Ink2")
    /// Icons and large text only.
    static let ink3 = Color("Ink3")
    /// The one filled action of a screen.
    static let primaryFill = Color("Primary")
    static let primaryOn = Color("PrimaryOn")
    /// The wishlist, nothing else.
    static let heart = Color("Heart")
    static let ok = Color("OK")
    static let warn = Color("Warn")
    static let bad = Color("Bad")
    /// The plate under a hero tip: Surface in light, near-black in dark.
    static let velvet = Color("Velvet")
    /// The rgb of every shadow; black in dark.
    static let shadowInk = Color("ShadowInk")
    /// The 1 pt outline of a painted tip.
    static let mat = Color("Mat")
    /// The lit edge of a tip.
    static let rim = Color("Rim")
}
